<?php
require 'config.php';require 'protecao.php';require 'campanha_lib.php';
if(!defined('TENANT_ID'))die('Tenant não identificado.');$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$arq=campanha_upload('arquivo','materiais');if(!$arq)throw new Exception('Envie o arquivo.');$capa=campanha_upload('imagem_capa','materiais');$pdo->prepare("INSERT INTO campanha_materiais (tenant_id,titulo,tipo,descricao,arquivo,imagem_capa,ativo) VALUES (?,?,?,?,?,?,1)")->execute([TENANT_ID,trim($_POST['titulo']??''),trim($_POST['tipo']??''),trim($_POST['descricao']??''),$arq,$capa]);header('Location: admin_campanha_materiais.php?ok=1');exit;}catch(Throwable $e){$msg="<div class='alert alert-danger'>".campanha_h($e->getMessage())."</div>";}}
if(isset($_GET['del'])){$pdo->prepare("DELETE FROM campanha_materiais WHERE id=? AND tenant_id=?")->execute([(int)$_GET['del'],TENANT_ID]);header('Location: admin_campanha_materiais.php');exit;}
$s=$pdo->prepare("SELECT * FROM campanha_materiais WHERE tenant_id=? ORDER BY id DESC");$s->execute([TENANT_ID]);$lista=$s->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Materiais</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-4"><div class="d-flex justify-content-between mb-3"><h3>Materiais da Campanha</h3><a href="admin_campanha.php" class="btn btn-outline-secondary">Voltar</a></div><?= $msg ?><div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm rounded-4"><div class="card-body p-4"><form method="post" enctype="multipart/form-data"><input name="titulo" class="form-control mb-3" placeholder="Título" required><select name="tipo" class="form-select mb-3"><option>Santinho</option><option>Logo</option><option>Jingle</option><option>Story</option><option>Feed</option><option>Adesivo</option><option>Manual da Marca</option><option>Kit Completo</option><option>Outro</option></select><textarea name="descricao" class="form-control mb-3" placeholder="Descrição"></textarea><label>Arquivo</label><input type="file" name="arquivo" class="form-control mb-3" required><label>Capa opcional</label><input type="file" name="imagem_capa" accept="image/*" class="form-control mb-3"><button class="btn btn-primary rounded-pill px-4">Adicionar</button></form></div></div></div><div class="col-lg-8"><div class="card border-0 shadow-sm rounded-4"><div class="card-body"><table class="table"><thead><tr><th>Material</th><th>Tipo</th><th>Downloads</th><th></th></tr></thead><tbody><?php foreach($lista as $m):?><tr><td><?= campanha_h($m['titulo']) ?></td><td><?= campanha_h($m['tipo']) ?></td><td><?= (int)$m['downloads'] ?></td><td class="text-end"><a href="campanha_download.php?id=<?= (int)$m['id'] ?>" class="btn btn-sm btn-outline-primary">Baixar</a> <a href="?del=<?= (int)$m['id'] ?>" onclick="return confirm('Excluir?')" class="btn btn-sm btn-outline-danger">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div></body></html>
